import * as React from "react";
import { cx } from "./cx";

export interface SeparatorProps extends React.HTMLAttributes<HTMLElement> {
  orientation?: "horizontal" | "vertical";
}

export function Separator({ orientation = "horizontal", className, ...props }: SeparatorProps) {
  if (orientation === "vertical") {
    return <span role="separator" aria-orientation="vertical" className={cx("rs-sep-v", className)} {...props} />;
  }
  return <hr className={cx("rs-sep", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Separator: a hairline, horizontal or vertical.
   Chrome uses --divider (the stronger of the two grid inks).
   The page 204 uses --grid-line. Same family, two steps. */
.rs-sep{border:none;border-top:1px solid var(--divider);margin:20px 0}
.rs-sep-v{display:inline-block;width:1px;align-self:stretch;background:var(--divider);margin:0 12px}
